 const runCaseResearch=async(id:string,quiet=false)=>{if(!id){setError('Select a case before researching it.');return;}setResearching(true);setResearchStatus('Researching your question and following useful links…');setError('');try{const d=await discoverCase(id);setAgentRun(d.data);await loadCaseData(id);const suite=await refreshIntelligenceSuite(id);setResearchStatus('');if(!quiet)notify('Research and source review complete: '+d.data.rounds+' research passes, '+d.data.queries.length+' queries, '+d.data.savedCount+' new sources, '+d.data.scrapedCount+' pages retrieved, '+d.data.leads.length+' follow-up leads. Claims, source overlap and research gaps '+(suite.claims&&suite.crossSource&&suite.gaps?'refreshed':'partially refreshed')+(suite.aiReview?'; AI review generated.':'.')+' Findings remain subject to source verification.');return d.data;}catch(e){const message=e instanceof Error?e.message:'Autonomous investigation failed.';if(/cancelled by the user/i.test(message)){setResearchStatus('RUN CANCELLED · Saved source records were preserved.');if(!quiet)notify('Investigation cancelled. Saved source records were preserved.');}else{setResearchStatus('');if(!quiet)setError(message);}return null;}finally{setResearching(false);}};
 const cancelCaseResearch=async(id:string)=>{if(!id)return;try{await request('/investigations/'+encodeURIComponent(id)+'/agent-run/cancel',{method:'POST',body:JSON.stringify({})});setResearchStatus('Stopping research…');notify('Cancellation requested. Work already saved will remain in the investigation.');}catch(e){setError(e instanceof Error?e.message:'Could not cancel this run. Refresh the investigation status.');}};
 const researchAllCases=async()=>{if(!cases.length){setError('Create a collection before finding more sources.');return;}setResearching(true);setError('');let saved=0,scraped=0,failed=0;for(let i=0;i<cases.length;i++){const item=cases[i];setResearchStatus('Agent researching case '+(i+1)+' of '+cases.length+': '+item.title);try{const d=await discoverCase(item.id);saved+=d.data.savedCount;scraped+=d.data.scrapedCount;}catch{failed++;}}setResearchStatus('');await loadCases();if(caseId)await loadCaseData(caseId);setResearching(false);notify('Batch agent run complete: '+saved+' new saved links, '+scraped+' pages retrieved, '+failed+' cases with provider errors. Discovered records remain unverified.');};
 const lookupArchive=async(e:FormEvent)=>{e.preventDefault();setArchiveNote('Looking up archive captures…');setError('');try{const d=await request<{data:{captures:Capture[];coverage:string}}>('/archives?url='+encodeURIComponent(archiveUrl));setCaptures(d.data.captures||[]);setArchiveNote(d.data.coverage);}catch(e){setArchiveNote('');setError(e instanceof Error?e.message:'Archive lookup failed.');}};
