 const addRelationship=async(e:FormEvent)=>{e.preventDefault();if(!caseId){setError('Choose a collection first.');return;}if(!relFrom||!relTo||!relEvidence){setError('Choose two items and a saved link to support the connection.');return;}if(relFrom===relTo){setError('Choose two different items for a connection.');return;}if(!entities.some(item=>key(item)===relFrom)||!entities.some(item=>key(item)===relTo)||!evidence.some(item=>key(item)===relEvidence)){setError('One of the selected items or links is no longer in this collection. Close this window and try again.');return;}try{await request('/investigations/'+encodeURIComponent(caseId)+'/relationships',{method:'POST',body:JSON.stringify({fromEntityId:relFrom,toEntityId:relTo,type:relType,evidenceIds:[relEvidence],confidence:'low',rationale:'Added by the user. Review the supporting link before relying on this connection.',verificationStatus:'unverified'})});setRelOpen(false);await loadCaseData(caseId);notify('Connection saved. Open the original link to review it.');}catch(err){setError(err instanceof Error?err.message:'Could not save this connection. Check the selected items and saved link, then try again.');}};
